SET LOCAL lock_timeout='15s';SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE resource_v3_test_result(result jsonb) ON COMMIT DROP;
DO $test$
DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype;id uuid:=gen_random_uuid();token text:=repeat('e',64);r jsonb;payload jsonb;
 dispatch_manifest jsonb;dispatch_answer jsonb;dispatch_pending boolean:=false;dispatch_rate boolean:=false;dispatch_accounting boolean:=false;dispatch_http bigint;dispatch_reserved numeric;dispatch_id uuid;
 qmanifest jsonb:='[ {"fixture":"resource-v3-measured-admission"} ]'::jsonb; proposal jsonb;review_id bigint;parent_task uuid;before_admission jsonb;after_admission jsonb;admitted boolean:=false;stale_rejected boolean:=false;headroom_rejected boolean:=false;preimage_rejected boolean:=false;
 badtoken boolean:=false;badfence boolean:=false;badstop boolean:=false;duplicate boolean:=false;badmetric boolean:=false;disabled_finish boolean:=false;
BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 PERFORM 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF a.owner_id IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR a.owner_fence<>3 OR a.stop_generation<>1 OR a.stopped OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.resource_probe_v3) THEN RAISE EXCEPTION 'RESOURCE_TEST_CURRENT_UNUSED_SLOT_REQUIRED';END IF;

 -- pg_net requests execute only after transaction commit. This subtransaction always rolls back before returning.
 BEGIN
 SELECT http_invocations INTO dispatch_http FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 SELECT reserved_request_usd INTO dispatch_reserved FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
 INSERT INTO population_top3000_202608_202609_v1.continuation_clear_queue_v6(clearing_id,kind,family_id,blocker_code,input_manifest,input_sha256,status,owner_id,owner_fence,stop_generation,scope_sha256,not_after,claimed_at,claim_expires_at)
 VALUES('rollback-dispatch-resource-v3','OPERATIONAL_REVIEW','RESOURCE','RESOURCE_CAPACITY_PROBE_AND_MEASURED_ADMISSION',qmanifest,encode(sha256(convert_to(qmanifest::text,'UTF8')),'hex'),'CLAIMED',a.owner_id,a.owner_fence,a.stop_generation,a.scope_sha256,clock_timestamp()+interval '30minutes',clock_timestamp(),clock_timestamp()+interval '30minutes');
 SELECT jsonb_object_agg(fn,encode(sha256(convert_to(pg_get_functiondef(fn::regprocedure),'UTF8')),'hex')) INTO dispatch_manifest FROM (VALUES
 ('population_top3000_202608_202609_v1.resource_probe_claim_v3(uuid,text)'),('population_top3000_202608_202609_v1.resource_probe_finish_v3(uuid,text,jsonb)'),('population_top3000_202608_202609_v1.resource_probe_dispatch_v3(text,bigint,bigint,text,bigint)'),('population_top3000_202608_202609_v1.resource_measured_admission_v3(text,bigint,bigint,text,uuid,jsonb,bigint)')) f(fn);
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RESOURCE_V3_DEPLOYMENT_VERIFIED',jsonb_build_object('approved',true,'actual_rollback_passed',true,'owner_id',a.owner_id,'owner_fence',a.owner_fence,'stop_generation',a.stop_generation,'scope_sha256',a.scope_sha256,'worker_sha256','1142afb4e20c2643bbba09f1f117eec96c436a285738cf741e035bfc7192af98','sql_code_manifest',dispatch_manifest,'producer','synthetic-producer','reviewer','synthetic-distinct-reviewer')) RETURNING event_id INTO review_id;
 dispatch_answer:=population_top3000_202608_202609_v1.resource_probe_dispatch_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-dispatch-resource-v3',review_id);dispatch_id:=(dispatch_answer->>'probe_id')::uuid;
 dispatch_accounting:=dispatch_answer->>'state'='DISPATCHED' AND dispatch_answer->>'probe_attempt'='5' AND (SELECT http_invocations=dispatch_http+1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) AND (SELECT reserved_request_usd=dispatch_reserved+1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) AND EXISTS(SELECT 1 FROM net.http_request_queue netq WHERE netq.id=(dispatch_answer->>'request_id')::bigint AND url='https://oxzabweahkoimtevbbny.supabase.co/functions/v1/population-top3000-resource-v3');
 BEGIN PERFORM population_top3000_202608_202609_v1.resource_probe_dispatch_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-dispatch-resource-v3',review_id);RAISE EXCEPTION 'UNKNOWN_DUPLICATE_DISPATCH_ACCEPTED';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='RESOURCE_V3_UNKNOWN_EFFECT_RECONCILIATION_REQUIRED' THEN dispatch_pending:=true;ELSE RAISE;END IF;END;
 UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET state='FAILED' WHERE probe_id=dispatch_id;
 BEGIN PERFORM population_top3000_202608_202609_v1.resource_probe_dispatch_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-dispatch-resource-v3',review_id);RAISE EXCEPTION 'RAPID_REDISPATCH_ACCEPTED';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='RESOURCE_V3_MEASUREMENT_RATE_BOUND' THEN dispatch_rate:=true;ELSE RAISE;END IF;END;
 IF NOT(dispatch_accounting AND dispatch_pending AND dispatch_rate) THEN RAISE EXCEPTION 'DISPATCH_FIXTURE_INCOMPLETE';END IF;
 RAISE EXCEPTION 'DISPATCH_FIXTURE_PASS_ROLLBACK';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'DISPATCH_FIXTURE_PASS_ROLLBACK' THEN RAISE;END IF;END;
 IF EXISTS(SELECT 1 FROM net.http_request_queue netq WHERE netq.id=(dispatch_answer->>'request_id')::bigint) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id=dispatch_id) OR (SELECT http_invocations FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) IS DISTINCT FROM dispatch_http OR (SELECT reserved_request_usd FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) IS DISTINCT FROM dispatch_reserved THEN RAISE EXCEPTION 'DISPATCH_NOT_ROLLED_BACK';END IF;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET http_invocations=http_invocations+1 WHERE singleton;
 UPDATE population_top3000_202608_202609_v1.pipeline_control SET reserved_request_usd=reserved_request_usd+1 WHERE singleton;
 INSERT INTO population_top3000_202608_202609_v1.resource_probe_v3(probe_id,owner_id,owner_fence,stop_generation,scope_sha256,token_sha256,state,expires_at,http_invocation_ordinal,probe_attempt,max_runtime_ms)
 VALUES(id,a.owner_id,a.owner_fence,a.stop_generation,a.scope_sha256,encode(sha256(convert_to(id::text||':'||token,'UTF8')),'hex'),'PENDING',clock_timestamp()+interval '3 minutes',a.http_invocations+1,5,30000);
 r:=population_top3000_202608_202609_v1.resource_probe_claim_v3(id,repeat('f',64));badtoken:=r->>'state'='DENIED';
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_fence=owner_fence+1 WHERE singleton;r:=population_top3000_202608_202609_v1.resource_probe_claim_v3(id,token);badfence:=r->>'state'='DENIED';RAISE EXCEPTION 'TEST_ROLLBACK_FENCE';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'TEST_ROLLBACK_FENCE' THEN RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stop_generation=stop_generation+1,stopped=true WHERE singleton;r:=population_top3000_202608_202609_v1.resource_probe_claim_v3(id,token);badstop:=r->>'state'='DENIED';RAISE EXCEPTION 'TEST_ROLLBACK_STOP';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'TEST_ROLLBACK_STOP' THEN RAISE;END IF;END;
 r:=population_top3000_202608_202609_v1.resource_probe_claim_v3(id,token);IF r->>'state' IS DISTINCT FROM 'CLAIMED' OR r->>'probe_attempt' IS DISTINCT FROM '5' THEN RAISE EXCEPTION 'SLOTS5_12_CLAIM_FAILED';END IF;
 r:=population_top3000_202608_202609_v1.resource_probe_claim_v3(id,token);duplicate:=r->>'state'='DENIED';
 payload:=jsonb_build_object('outcome','SUCCEEDED','observed_at',clock_timestamp(),'metrics_http_status',200,'source_sha256',repeat('a',64),'metrics',jsonb_build_array(jsonb_build_object('filesystem_id',repeat('b',64),'mountpoint','/data','available_bytes',100000000000,'free_bytes',110000000000,'size_bytes',200000000000)),'error_code',NULL,'elapsed_ms',10,'capabilities',jsonb_build_object('sec_user_agent_configured',false,'sec_contact_email_configured',false,'massive_key_configured',false));
 BEGIN PERFORM population_top3000_202608_202609_v1.resource_probe_finish_v3(id,token,jsonb_set(payload,'{metrics,0,available_bytes}','-1'));RAISE EXCEPTION 'BAD_METRIC_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM='INVALID_FILESYSTEM_METRIC' THEN badmetric:=true;ELSE RAISE;END IF;END;
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_control SET enabled=false WHERE singleton;r:=population_top3000_202608_202609_v1.resource_probe_finish_v3(id,token,payload);disabled_finish:=r->>'state'='DENIED';RAISE EXCEPTION 'TEST_ROLLBACK_DISABLED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'TEST_ROLLBACK_DISABLED' THEN RAISE;END IF;END;
 r:=population_top3000_202608_202609_v1.resource_probe_finish_v3(id,token,payload);IF r->>'state' IS DISTINCT FROM 'RECORDED' THEN RAISE EXCEPTION 'RESOURCE_FINISH_FAILED';END IF;
 r:=population_top3000_202608_202609_v1.resource_probe_finish_v3(id,token,payload);IF r->>'state' IS DISTINCT FROM 'ALREADY_RECORDED' THEN RAISE EXCEPTION 'RESOURCE_REPLAY_FAILED';END IF;

 -- Exercise measured finite cap admission with synthetic metrics; roll back nested mutation while retaining assertion results.
 SELECT task_id INTO parent_task FROM population_top3000_202608_202609_v1.pipeline_task WHERE status IN('READY','BLOCKED') ORDER BY CASE WHEN family_id='CTX02' AND stage='ACQUIRE' THEN 0 ELSE 1 END,task_id LIMIT 1;
 INSERT INTO population_top3000_202608_202609_v1.continuation_clear_queue_v6(clearing_id,kind,family_id,blocker_code,input_manifest,input_sha256,status,owner_id,owner_fence,stop_generation,scope_sha256,not_after,claimed_at,claim_expires_at)
 VALUES('rollback-resource-v3','OPERATIONAL_REVIEW','RESOURCE','RESOURCE_CAPACITY_PROBE_AND_MEASURED_ADMISSION',qmanifest,encode(sha256(convert_to(qmanifest::text,'UTF8')),'hex'),'CLAIMED',a.owner_id,a.owner_fence,a.stop_generation,a.scope_sha256,clock_timestamp()+interval '30minutes',clock_timestamp(),clock_timestamp()+interval '30minutes');
 SELECT jsonb_build_object('old_max_relation_bytes',p.budget_evidence#>>'{resource_limits,max_relation_bytes}','old_max_source_bytes',ac.max_source_bytes::text,'new_max_relation_bytes',(p.budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint+1000000000,'new_max_source_bytes',ac.max_source_bytes,'original_deadline',p.deadline::text,'probe_result_sha256',v.result_sha256,'successor_task_id',parent_task) INTO proposal FROM population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.resource_probe_v3 v WHERE p.singleton AND ac.singleton AND v.probe_id=id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RESOURCE_V3_MEASURED_ADMISSION_REVIEW',jsonb_build_object('approved',true,'clearing_id','rollback-resource-v3','input_sha256',encode(sha256(convert_to(qmanifest::text,'UTF8')),'hex'),'proposal_sha256',encode(sha256(convert_to(proposal::text,'UTF8')),'hex'),'probe_result_sha256',proposal->>'probe_result_sha256','owner_id',a.owner_id,'owner_fence',a.owner_fence,'stop_generation',a.stop_generation,'scope_sha256',a.scope_sha256,'producer','synthetic-producer','reviewer','synthetic-distinct-reviewer')) RETURNING event_id INTO review_id;
 BEGIN
 PERFORM population_top3000_202608_202609_v1.resource_measured_admission_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-resource-v3',id,jsonb_set(proposal,'{old_max_source_bytes}','"1"'::jsonb),review_id);
 RAISE EXCEPTION 'BAD_PREIMAGE_ACCEPTED';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='RESOURCE_V3_EXACT_PREIMAGE_PROPOSAL_REQUIRED' THEN preimage_rejected:=true;ELSE RAISE;END IF;END;
 BEGIN
 UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result=jsonb_set(result,'{observed_at}',to_jsonb((clock_timestamp()-interval '11minutes')::text)) WHERE probe_id=id;
 UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result_sha256=encode(sha256(convert_to(result::text,'UTF8')),'hex') WHERE probe_id=id;
 PERFORM population_top3000_202608_202609_v1.resource_measured_admission_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-resource-v3',id,proposal,review_id);
 RAISE EXCEPTION 'STALE_METRIC_ACCEPTED';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='RESOURCE_V3_FRESH_MEASUREMENT_REQUIRED' THEN stale_rejected:=true;ELSE RAISE;END IF;END;
 BEGIN
 UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result=jsonb_set(result,'{metrics,0,available_bytes}',to_jsonb((SELECT floor(20000000000+1000000000+((proposal->>'new_max_relation_bytes')::bigint-coalesce(sum(pg_total_relation_size(c.oid)),0)+(a.max_source_bytes-a.stored_bytes)-1000000000)/2) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relkind IN('r','m')))) WHERE probe_id=id;
 UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result_sha256=encode(sha256(convert_to(result::text,'UTF8')),'hex') WHERE probe_id=id;
 IF (SELECT (result#>>'{metrics,0,available_bytes}')::numeric-1000000000 FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id=id)<20000000000 THEN RAISE EXCEPTION 'HEADROOM_FIXTURE_INCREMENT_PRECONDITION_FAILED';END IF;
 IF (SELECT (v.result#>>'{metrics,0,available_bytes}')::numeric-((proposal->>'new_max_relation_bytes')::bigint-(SELECT sum(pg_total_relation_size(c.oid)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relkind IN('r','m'))+a.max_source_bytes-a.stored_bytes) FROM population_top3000_202608_202609_v1.resource_probe_v3 v WHERE probe_id=id)>=20000000000 THEN RAISE EXCEPTION 'HEADROOM_FIXTURE_TOTAL_GROWTH_PRECONDITION_FAILED';END IF;
 PERFORM population_top3000_202608_202609_v1.resource_measured_admission_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-resource-v3',id,jsonb_set(proposal,'{probe_result_sha256}',to_jsonb((SELECT result_sha256 FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id=id))),review_id);
 RAISE EXCEPTION 'INSUFFICIENT_HEADROOM_ACCEPTED';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='RESOURCE_V3_MEASURED_HEADROOM_INSUFFICIENT' THEN headroom_rejected:=true;ELSE RAISE;END IF;END;
 SELECT (to_jsonb(ac)-'max_source_bytes')||jsonb_build_object('pipeline',to_jsonb(pc)-'budget_evidence','budget',pc.budget_evidence#-'{resource_limits,max_relation_bytes}') INTO before_admission FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
 r:=population_top3000_202608_202609_v1.resource_measured_admission_v3(a.owner_id,a.owner_fence,a.stop_generation,'rollback-resource-v3',id,proposal,review_id);
 admitted:=r->>'state'='ADMITTED';
 SELECT (to_jsonb(ac)-'max_source_bytes')||jsonb_build_object('pipeline',to_jsonb(pc)-'budget_evidence','budget',pc.budget_evidence#-'{resource_limits,max_relation_bytes}') INTO after_admission FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
 IF before_admission IS DISTINCT FROM after_admission OR NOT(admitted AND preimage_rejected AND stale_rejected AND headroom_rejected) THEN RAISE EXCEPTION 'MEASURED_ADMISSION_COUNTER_HISTORY_TEST_FAILED';END IF;
 IF NOT(badtoken AND badfence AND badstop AND duplicate AND badmetric AND disabled_finish) OR (SELECT count(*) FROM population_top3000_202608_202609_v1.resource_probe_v1)<>3 THEN RAISE EXCEPTION 'RESOURCE_TEST_INCOMPLETE';END IF;
 INSERT INTO resource_v3_test_result VALUES(jsonb_build_object('result','PASS_RESOURCE_SLOTS5_12_ROLLBACK','old_probes_preserved',3,'new_slot',5,'bad_token_rejected',badtoken,'stale_fence_rejected',badfence,'later_stop_rejected',badstop,'duplicate_claim_rejected',duplicate,'invalid_metric_rejected',badmetric,'disabled_pipeline_finish_rejected',disabled_finish,'replay_idempotent',true,'actual_internal_http_calls',0,'provider_calls',0,'dispatch_slot5_accounting_verified',dispatch_accounting,'unknown_duplicate_dispatch_rejected',dispatch_pending,'dispatch_rate_bound_rejected',dispatch_rate,'transactional_http_queue_rolled_back',true,'measured_admission_tested',admitted,'stale_metric_rejected',stale_rejected,'insufficient_headroom_rejected',headroom_rejected,'wrong_preimage_rejected',preimage_rejected,'all_counters_and_original_deadline_preserved',before_admission=after_admission,'production_changes_rolled_back',true));
END; $test$;
SELECT result FROM resource_v3_test_result;
ROLLBACK;
